                    tx = rec::Sub(gocpp::recv(new big::Int{}), x0, x1);
                    z0 = rec::Mul(gocpp::recv(new big::Int{}), x0, x0);
                    z2 = rec::Mul(gocpp::recv(new big::Int{}), x1, x1);
                    z1 = rec::Mul(gocpp::recv(new big::Int{}), tx, tx);
                    rec::Neg(gocpp::recv(z1), z1);
                    rec::Add(gocpp::recv(z1), z1, z0);
                    rec::Add(gocpp::recv(z1), z1, z2);
                    print("karatsubaSqr wrong\n"_s);
                    trace("x "_s, gocpp::InitPtr<golang::math::big::Int>([=](auto& y) {
                        y.abs = x;
                    }));
                    trace("z "_s, gocpp::InitPtr<golang::math::big::Int>([=](auto& y) {
                        y.abs = z;
                    }));
                    trace("zz"_s, gocpp::InitPtr<golang::math::big::Int>([=](auto& y) {
                        y.abs = zz;
                    }));
                    trace("x0"_s, x0);
                    trace("x1"_s, x1);
                    trace("z0"_s, z0);
                    trace("z1"_s, z1);
                    trace("z2"_s, z2);
