    // ifmt returns the debug formatting of the Int x: 0xHEX.
    gocpp::string ifmt(golang::math::big::Int* x)
    {
        auto [neg, s, t] = std::tuple{""_s, rec::Text(gocpp::recv(x), 16), ""_s};
        if(s == ""_s)
        {
            // happens for denormalized zero
            s = "0x0"_s;
        }
        if(s[0] == '-')
        {
            std::tie(neg, s) = std::tuple{"-"_s, s.make_slice(1)};
        }

        // Add _ between words.
        // digits per chunk
        auto D = _W / 4;
        for(; len(s) > D; )
        {
            std::tie(s, t) = std::tuple{s.make_slice(0, len(s) - D), s.make_slice(len(s) - D) + "_"_s + t};
        }
        return neg + s + t;
    }

    // trace prints a single debug value.
    void trace(gocpp::string name, golang::math::big::Int* x)
    {
        print(name, "="_s, ifmt(x), "\n"_s);
    }

